#include "biocore/domain/variant_annotation.hpp"
#include <stdexcept>
namespace{using namespace biocore::domain;void require(bool c){if(!c)throw std::runtime_error("contig annotation test failed");} ReferenceDatabaseMetadata m(){return {"db","DB","1",1U,{ReferenceAssembly::grch38,{}},"file:///db",std::string(64U,'d')};}}
int main(){ ContigTableBuilder qb{ReferenceAssembly::grch38};qb.add_contig("1",{"chr1"});qb.add_contig("2",{"chr2"});auto q=qb.build();ContigTableBuilder dbb{ReferenceAssembly::grch38};dbb.add_contig("2",{"chr2"});auto dct=dbb.build();auto d2=*dct.resolve("2"); ReferenceDatabaseRecord rr{{d2,3U,4U},{"A",VariantType::unknown,false},{"G",VariantType::snv,false},"r",{}};auto db=ReferenceDatabase::build(m(),dct,{rr});auto q2=*q.resolve("2");VariantRecord v;v.locus={q2,3U,4U};v.reference={"A",VariantType::unknown,false};v.alternates.push_back({"G",VariantType::snv,false});auto r=annotate_variant({ReferenceAssembly::grch38,{}},q,v,{&db});require(r.alternates[0].allele_annotations.size()==1U); }
